#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_CLIENTS 64
#define MSG_BUF_SIZE 512
#define CMD_BUF_SIZE 128

typedef enum { ROLE_GUEST = 0, ROLE_USER = 1, ROLE_ADMIN = 2 } role_t;

typedef struct {
    int fd;
    role_t role;
    char username[32];
    uint32_t msg_count;
} client_t;

typedef struct {
    uint16_t type;
    uint16_t flags;
    uint32_t payload_len;
    char payload[MSG_BUF_SIZE];
} message_t;

typedef struct {
    uint16_t type;
    uint16_t flags;
    uint32_t cmd_id;
    char args[CMD_BUF_SIZE];
} command_t;

static client_t clients[MAX_CLIENTS];
static int num_clients = 0;
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;
static int admin_broadcast_enabled;

void load_config(void) {
    const char *val = getenv("CHAT_ADMIN_BROADCAST");
    if (val) {
        admin_broadcast_enabled = atoi(val);
    } else {
        admin_broadcast_enabled = 0;
    }
}

static void broadcast_message(const char *msg, int sender_fd) {
    pthread_mutex_lock(&clients_lock);
    for (int i = 0; i < num_clients; i++) {
        if (clients[i].fd != sender_fd) {
            send(clients[i].fd, msg, strlen(msg), MSG_NOSIGNAL);
        }
    }
    pthread_mutex_unlock(&clients_lock);
}

static int find_client(int fd) {
    for (int i = 0; i < num_clients; i++) {
        if (clients[i].fd == fd) return i;
    }
    return -1;
}

static void execute_admin_command(command_t *cmd, int client_fd) {
    role_t role = ROLE_GUEST;
    int found = 0;

    pthread_mutex_lock(&clients_lock);
    int idx = find_client(client_fd);
    if (idx >= 0) {
        found = 1;
        role = clients[idx].role;
    }
    pthread_mutex_unlock(&clients_lock);

    if (!found) return;

    if (role != ROLE_ADMIN) {
        const char *deny = "Permission denied\n";
        send(client_fd, deny, strlen(deny), MSG_NOSIGNAL);
        return;
    }

    if (cmd->cmd_id == 1) {
        char buf[256];
        snprintf(buf, sizeof(buf), "[ADMIN] %s\n", cmd->args);
        broadcast_message(buf, client_fd);
    } else if (cmd->cmd_id == 2) {
        /* kick user by name */
        pthread_mutex_lock(&clients_lock);
        for (int i = 0; i < num_clients; i++) {
            if (strcmp(clients[i].username, cmd->args) == 0) {
                close(clients[i].fd);
                clients[i] = clients[--num_clients];
                break;
            }
        }
        pthread_mutex_unlock(&clients_lock);
    }
}

static void process_packet(void *packet_buf, int client_fd) {
    /*
     * Protocol: first 2 bytes are 'type' field.
     * type == 1: message_t (chat message)
     * type == 2: command_t (admin command)
     *
     * We use the type field to determine struct interpretation.
     * The config CHAT_ADMIN_BROADCAST controls whether type-2
     * packets from admins get echoed back for audit logging.
     */
    uint16_t pkt_type = *(uint16_t *)packet_buf;

    if (pkt_type == 1) {
        message_t *msg = (message_t *)packet_buf;
        msg->payload[msg->payload_len < MSG_BUF_SIZE ? msg->payload_len : MSG_BUF_SIZE - 1] = '\0';

        char formatted[MSG_BUF_SIZE + 64];
        int have_client = 0;

        pthread_mutex_lock(&clients_lock);
        int idx = find_client(client_fd);
        if (idx >= 0) {
            have_client = 1;
            snprintf(formatted, sizeof(formatted), "<%s> %s\n",
                     clients[idx].username, msg->payload);
            clients[idx].msg_count++;
        }
        pthread_mutex_unlock(&clients_lock);

        if (have_client) {
            broadcast_message(formatted, client_fd);
        }
    } else if (pkt_type == 2) {
        /* Verify sender is admin BEFORE any processing */
        int denied = 0;

        pthread_mutex_lock(&clients_lock);
        int idx = find_client(client_fd);
        if (idx < 0 || clients[idx].role != ROLE_ADMIN) {
            denied = 1;
        }
        pthread_mutex_unlock(&clients_lock);

        if (denied) {
            const char *deny = "Permission denied\n";
            send(client_fd, deny, strlen(deny), MSG_NOSIGNAL);
            return;
        }

        command_t *cmd = (command_t *)packet_buf;
        cmd->args[CMD_BUF_SIZE - 1] = '\0';

        if (admin_broadcast_enabled) {
            /*
             * Audit log: format the command args safely as a log line.
             * No type reinterpretation - use the command_t directly.
             */
            char logbuf[CMD_BUF_SIZE + 32];
            snprintf(logbuf, sizeof(logbuf), "[AUDIT] %s\n", cmd->args);
            send(client_fd, logbuf, strlen(logbuf), MSG_NOSIGNAL);
        }
        execute_admin_command(cmd, client_fd);
    }
}

static void *client_handler(void *arg) {
    int fd = *(int *)arg;
    free(arg);

    /* Initial handshake: receive username and role token */
    char handshake[64];
    memset(handshake, 0, sizeof(handshake));
    ssize_t n = recv(fd, handshake, sizeof(handshake) - 1, 0);
    if (n <= 0) { close(fd); return NULL; }

    pthread_mutex_lock(&clients_lock);
    if (num_clients >= MAX_CLIENTS) {
        pthread_mutex_unlock(&clients_lock);
        close(fd);
        return NULL;
    }
    int idx = num_clients++;
    clients[idx].fd = fd;
    clients[idx].msg_count = 0;

    /* Parse: "username:role_token" */
    char *colon = strchr(handshake, ':');
    if (colon) {
        *colon = '\0';
        strncpy(clients[idx].username, handshake, 31);
        clients[idx].username[31] = '\0';
        uint32_t token = (uint32_t)strtoul(colon + 1, NULL, 16);
        /* Role assignment: token's upper nibble determines role */
        clients[idx].role = (role_t)((token >> 28) & 0x3);
    } else {
        strncpy(clients[idx].username, handshake, 31);
        clients[idx].username[31] = '\0';
        clients[idx].role = ROLE_GUEST;
    }
    pthread_mutex_unlock(&clients_lock);

    /* Main receive loop */
    char recv_buf[sizeof(message_t)];
    while (1) {
        memset(recv_buf, 0, sizeof(recv_buf));
        n = recv(fd, recv_buf, sizeof(recv_buf), 0);
        if (n <= 0) break;
        process_packet(recv_buf, fd);
    }

    pthread_mutex_lock(&clients_lock);
    int cidx = find_client(fd);
    if (cidx >= 0) {
        clients[cidx] = clients[--num_clients];
    }
    pthread_mutex_unlock(&clients_lock);
    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    load_config();

    int port = 9090;
    const char *port_env = getenv("CHAT_PORT");
    if (port_env) port = atoi(port_env);

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) {
        perror("socket");
        return 1;
    }
    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(srv);
        return 1;
    }
    if (listen(srv, 16) < 0) {
        perror("listen");
        close(srv);
        return 1;
    }

    printf("Chat server on port %d (admin_broadcast=%d)\n", port, admin_broadcast_enabled);

    while (1) {
        int *cfd = malloc(sizeof(int));
        if (!cfd) continue;
        *cfd = accept(srv, NULL, NULL);
        if (*cfd < 0) { free(cfd); continue; }
        pthread_t t;
        pthread_create(&t, NULL, client_handler, cfd);
        pthread_detach(t);
    }
    return 0;
}
